#include <iostream>
namespace Outer {
  class Base {
  public:
    void print() { std::cout << "Base::print()\n"; }
  };
  class Inner : public Base {
  public:
    void print() { std::cout << "Inner::print()\n"; }
    void callPrint() { print(); /*Which print?*/ }
    void callBasePrint() { Base::print();}
  };
}
int main() {
  Outer::Inner inner;
  inner.callPrint();
  inner.callBasePrint();
  return 0;
}
